function main({ segments_json, level, style, avoid_words, source }) {
  const JS = (t, d) => { try { const v = JSON.parse(t || ''); return (v && typeof v === 'object') ? v : d; } catch (e) { return d; } };
  const segs = (JS(segments_json, []) || []).map((s) => String(s || '').trim()).filter(Boolean);
  const N = segs.length;
  const lv = String(level || '').trim().toUpperCase();
  const lvBig = lv === 'B2' ? 'B2' : 'B1';

  /* 要产的低档：母稿 B2 → B1/A2/A1-；母稿 B1 → A2/A1-（只能往下，不能往上） */
  const TARGETS = { B2: ['B1', 'A2', 'A1'], B1: ['A2', 'A1'] };
  const targets = TARGETS[lvBig] || [];

  /* 编号段落骨架：第 i 段 → 第 i 段，严格 1:1（与 GEN 的 gist_lines 同构，便于沿用同一套提示词） */
  const lines = [];
  segs.forEach((s, i) => { lines.push('【段 ' + (i + 1) + '】' + s); });
  const seg_lines = lines.join('\n\n');

  /* 主题摘要：取首段前若干词，供标题/校验引用（图 B 不再单独跑摘要节点） */
  const summary = segs.length ? segs[0].split(/\s+/).slice(0, 24).join(' ') : '';

  const avoid = JS(avoid_words, {});
  const pick = (k) => JSON.stringify(avoid[k] || avoid[k.toUpperCase()] || []);

  /* 🔴 每段词数规格与 GEN **完全一致、不改**（Bryan 2026-09-21 定案）。
     但图 B 的段数由母稿决定（不是固定 12 段）⇒ 全文区间必须**按 N 现算**，
     否则 N=11 时模型仍按 12 段的总量写，各档会集体超标（实测 A1- 23 词/段、B1 51 词/段）。 */
  const PER = { A1: [11, 14], A2: [20, 22], B1: [28, 35], B2: [41, 50] };
  const spec = {};
  Object.keys(PER).forEach((k) => {
    const lo = PER[k][0] * N, hi = PER[k][1] * N, tg = Math.round((lo + hi) / 2);
    spec[k] = { per: PER[k][0] + '–' + PER[k][1], lo: lo, hi: hi, tgt: tg };
  });
  const sp = (k, f) => String(spec[k][f]);

  return {
    seg_lines: seg_lines,
    seg_count: String(N),
    summary: summary,
    level: lvBig,
    level_big: lvBig,
    style: String(style || 'default'),
    source: String(source || '').trim(),
    targets_json: JSON.stringify(targets),
    target_count: String(targets.length),
    avoid_a1: pick('A1'), avoid_a2: pick('A2'), avoid_b1: pick('B1'), avoid_b2: pick('B2'),
    /* 各档「全文字数」按段数现算（供生成节点插值）*/
    spec_json: JSON.stringify(spec),
    a1_lo: sp('A1', 'lo'), a1_hi: sp('A1', 'hi'), a1_tgt: sp('A1', 'tgt'), a1_per: spec.A1.per,
    a2_lo: sp('A2', 'lo'), a2_hi: sp('A2', 'hi'), a2_tgt: sp('A2', 'tgt'), a2_per: spec.A2.per,
    b1_lo: sp('B1', 'lo'), b1_hi: sp('B1', 'hi'), b1_tgt: sp('B1', 'tgt'), b1_per: spec.B1.per,
    b2_lo: sp('B2', 'lo'), b2_hi: sp('B2', 'hi'), b2_tgt: sp('B2', 'tgt'), b2_per: spec.B2.per,
    /* 母稿正文（各段拼接）—— 它就是入库的高档稿件 */
    mat_text: segs.join('\n\n'),
    ok: (N >= 3 && targets.length > 0) ? 'true' : 'false',
  };
}

function main({ style }) {
  const STYLES = {
    default: "Neutral, clear, natural expository prose — the platform's standard graded-reading style, without imitating a specific author.",
    hemingway: "Ernest Hemingway: short declarative sentences, few adjectives, concrete nouns and action verbs, understated emotion (iceberg theory).",
    austen: "Jane Austen: elegant, witty prose with keen social observation and ironic precision; polished, ironic and precise.",
    ohenry: "O. Henry: warm humor, vivid characters and a surprising ironic twist at the end.",
    twain: "Mark Twain: colloquial, humorous and lightly satirical; down-to-earth language, witty observations and folksy charm.",
    dickens: "Charles Dickens: rich narrative with vivid characters, social observation and a touch of warmth and humor.",
    orwell: "George Orwell: clear, plain, incisive prose; direct and morally serious, with concrete imagery.",
    shakespeare: "William Shakespeare: elevated, rhetorical and lyrical; rich in imagery, metaphor and rhythm."
  };
  const key = String(style || '').toLowerCase();
  const base = STYLES[key] || STYLES.default;
  const instruction = base + " Keep all facts, names, numbers and the required structure (title, paragraphs, glossary) unchanged — only the writing style differs. Adapt sentence length and vocabulary to the target CEFR level.";
  return { style_key: (key in STYLES) ? key : 'default', style_instruction: instruction };
}

